import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.ClgMjOt7.js";const g=JSON.parse('{"title":"テレメトリ & クラッシュレポート","description":"テレメトリ収集 (Firebase Crashlytics / Performance Monitoring) の仕組みとプライバシー設計","frontmatter":{"title":"テレメトリ & クラッシュレポート","description":"テレメトリ収集 (Firebase Crashlytics / Performance Monitoring) の仕組みとプライバシー設計"},"headers":[],"relativePath":"features/telemetry.md","filePath":"features/telemetry.md","lastUpdated":1786168778000}'),l={name:"features/telemetry.md"};function n(r,e,o,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="テレメトリ-クラッシュレポート" tabindex="-1">テレメトリ &amp; クラッシュレポート <a class="header-anchor" href="#テレメトリ-クラッシュレポート" aria-label="Permalink to &quot;テレメトリ &amp; クラッシュレポート&quot;">​</a></h1><p>Palleria は、アプリの安定性向上およびパフォーマンス改善のためにテレメトリ収集（ログ送信）機能を搭載しています。ただし、プライバシー尊重のためデフォルトでは無効化（オプトイン方式）されています。</p><hr><h2 id="収集メカニズム" tabindex="-1">収集メカニズム <a class="header-anchor" href="#収集メカニズム" aria-label="Permalink to &quot;収集メカニズム&quot;">​</a></h2><p>テレメトリ機能が有効化された場合、以下の 2 つのサービスが動作します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">サービス</th><th style="text-align:left;">クラス / SDK</th><th style="text-align:left;">目的・収集内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Firebase Crashlytics</strong></td><td style="text-align:left;"><code>FirebaseCrashlytics</code></td><td style="text-align:left;">未捕獲のクラッシュログ、例外スタックトレース、OS バージョン、端末モデル</td></tr><tr><td style="text-align:left;"><strong>Firebase Performance</strong></td><td style="text-align:left;"><code>FirebasePerformance</code></td><td style="text-align:left;">アプリ起動時間、ネットワークリクエストの応答時間（レスポンスタイム）</td></tr></tbody></table><hr><h2 id="ソースコード実装仕様" tabindex="-1">ソースコード実装仕様 <a class="header-anchor" href="#ソースコード実装仕様" aria-label="Permalink to &quot;ソースコード実装仕様&quot;">​</a></h2><h3 id="_1-オプトイン設定-appsettings-sendtelemetry" tabindex="-1">1. オプトイン設定 (<code>AppSettings.sendTelemetry</code>) <a class="header-anchor" href="#_1-オプトイン設定-appsettings-sendtelemetry" aria-label="Permalink to &quot;1. オプトイン設定 (`AppSettings.sendTelemetry`)&quot;">​</a></h3><ul><li><code>AppSettings.sendTelemetry</code>: データストア項目 (<code>sendTelemetry</code>, デフォルト値 <code>false</code>)。</li><li>「設定」&gt;「データ設定」画面 (<code>DataSettingsScreen</code>) の「テレメトリデータを送信」スイッチからいつでも変更可能です。</li></ul><h3 id="_2-動的な有効化-無効化制御-illustiaapplication" tabindex="-1">2. 動的な有効化 / 無効化制御 (<code>IllustiaApplication</code>) <a class="header-anchor" href="#_2-動的な有効化-無効化制御-illustiaapplication" aria-label="Permalink to &quot;2. 動的な有効化 / 無効化制御 (`IllustiaApplication`)&quot;">​</a></h3><p>アプリ起動時（<code>IllustiaApplication.onCreate</code>）および設定変更時に、設定値に応じて動的に SDK の有効・無効を切り替えます。</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// settings.sendTelemetry が false の場合、送信処理は一切行われません</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FirebaseCrashlytics.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setCrashlyticsCollectionEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(settings.sendTelemetry)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FirebasePerformance.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().isPerformanceCollectionEnabled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> settings.sendTelemetry</span></span></code></pre></div><h3 id="_3-ローカルクラッシュハンドラー-crashhandler" tabindex="-1">3. ローカルクラッシュハンドラー (<code>CrashHandler</code>) <a class="header-anchor" href="#_3-ローカルクラッシュハンドラー-crashhandler" aria-label="Permalink to &quot;3. ローカルクラッシュハンドラー (`CrashHandler`)&quot;">​</a></h3><p>外部サービスへの送信有無にかかわらず、アプリ内では <code>CrashHandler</code>（<code>Thread.UncaughtExceptionHandler</code>）が未補獲の例外を捕捉します。</p><ul><li><strong>リソースエラー判定</strong>: リソース読み込み失敗 (<code>Resources.NotFoundException</code> / <code>InflateException</code>) の特定。</li><li><strong>ストレージ権限指示</strong>: 保存先ストレージのアクセス権限エラー時、適切な復旧案内を表示。</li><li><strong>キャンセルの安全処理</strong>: Coroutine のキャンセル例外 (<code>CancellationException</code>) はクラッシュ扱いから除外。</li></ul><hr><h2 id="プライバシー-データセキュリティ" tabindex="-1">プライバシー &amp; データセキュリティ <a class="header-anchor" href="#プライバシー-データセキュリティ" aria-label="Permalink to &quot;プライバシー &amp; データセキュリティ&quot;">​</a></h2><ul><li><strong>完全オプトイン</strong>: 初期状態で送信が無効になっているため、同意なしにデータが外部へ送信されることはありません。</li><li><strong>個人情報の非収集</strong>: Pixiv アカウントのログイン情報（トークン、パスワード）、検索履歴、閲覧履歴、保存された画像データがテレメトリに含まれることはありません。</li></ul>',19)])])}const k=t(l,[["render",n]]);export{g as __pageData,k as default};
